+func getActualFlag(name string, flagSet *flag.FlagSet) *flag.Flag {
+	var found *flag.Flag
+	flagSet.Visit(func(f *flag.Flag) {
+		if f.Name == name {
+			found = f
+		}
+	})
+	return found
+}
